// Fixed-chunk C boundary probe for the pinned Tree-sitter UTF-16 decoders.
// This console owns only generated bytes; it is not an app or package test.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "unicode.h"

typedef struct {
  const char *name;
  uint8_t bytes[4];
  uint32_t declared_length;
  int32_t expected_code_point;
  uint32_t expected_consumed;
} Case;

static int check_case(const Case *test, int big_endian) {
  int32_t actual_code_point = 0;
  uint32_t actual_consumed = big_endian
    ? ts_decode_utf16_be(test->bytes, test->declared_length, &actual_code_point)
    : ts_decode_utf16_le(test->bytes, test->declared_length, &actual_code_point);
  int pass = actual_code_point == test->expected_code_point &&
    actual_consumed == test->expected_consumed;
  printf("case=%s endian=%s declared=%u codepoint=%d consumed=%u expected_codepoint=%d expected_consumed=%u pass=%d\n",
    test->name, big_endian ? "BE" : "LE", test->declared_length,
    actual_code_point, actual_consumed, test->expected_code_point,
    test->expected_consumed, pass);
  if (!pass) {
    fprintf(stderr, "UTF16_BOUNDARY_MISMATCH case=%s endian=%s\n",
      test->name, big_endian ? "BE" : "LE");
  }
  return pass;
}

static int matrix(void) {
  static const Case little[] = {
    {"empty", {0x41, 0x00, 0x00, 0x00}, 0, TS_DECODE_ERROR, 0},
    {"one_byte", {0x41, 0x00, 0x00, 0x00}, 1, TS_DECODE_ERROR, 1},
    {"lead_with_poison", {0x3e, 0xd8, 0x8b, 0xdd}, 2, 0xd83e, 2},
    {"bmp_A", {0x41, 0x00, 0x00, 0x00}, 2, 0x41, 2},
    {"bmp_CJK", {0x2d, 0x4e, 0x00, 0x00}, 2, 0x4e2d, 2},
    {"valid_pair", {0x3e, 0xd8, 0x8b, 0xdd}, 4, 0x1f98b, 4},
  };
  static const Case big[] = {
    {"empty", {0x00, 0x41, 0x00, 0x00}, 0, TS_DECODE_ERROR, 0},
    {"one_byte", {0x00, 0x41, 0x00, 0x00}, 1, TS_DECODE_ERROR, 1},
    {"lead_with_poison", {0xd8, 0x3e, 0xdd, 0x8b}, 2, 0xd83e, 2},
    {"bmp_A", {0x00, 0x41, 0x00, 0x00}, 2, 0x41, 2},
    {"bmp_CJK", {0x4e, 0x2d, 0x00, 0x00}, 2, 0x4e2d, 2},
    {"valid_pair", {0xd8, 0x3e, 0xdd, 0x8b}, 4, 0x1f98b, 4},
  };
  unsigned failures = 0;
  for (size_t i = 0; i < sizeof(little) / sizeof(little[0]); i++) {
    failures += !check_case(&little[i], 0);
    failures += !check_case(&big[i], 1);
  }
  printf("cases=12 failures=%u\n", failures);
  return failures ? 65 : 0;
}

static int true_two_byte_allocation(int big_endian) {
  uint8_t *chunk = malloc(2);
  if (!chunk) {
    fputs("allocation failed\n", stderr);
    return 70;
  }
  chunk[0] = big_endian ? 0xd8 : 0x3e;
  chunk[1] = big_endian ? 0x3e : 0xd8;
  int32_t actual_code_point = 0;
  uint32_t actual_consumed = big_endian
    ? ts_decode_utf16_be(chunk, 2, &actual_code_point)
    : ts_decode_utf16_le(chunk, 2, &actual_code_point);
  printf("allocation=2 endian=%s declared=2 codepoint=%d consumed=%u expected_codepoint=%d expected_consumed=2\n",
    big_endian ? "BE" : "LE", actual_code_point, actual_consumed, 0xd83e);
  free(chunk);
  return actual_code_point == 0xd83e && actual_consumed == 2 ? 0 : 65;
}

int main(int argc, char **argv) {
  if (argc == 1) return matrix();
  if (argc == 2 && strcmp(argv[1], "--true-two-byte-le") == 0) {
    return true_two_byte_allocation(0);
  }
  if (argc == 2 && strcmp(argv[1], "--true-two-byte-be") == 0) {
    return true_two_byte_allocation(1);
  }
  fputs("usage: utf16-decoder-boundary [--true-two-byte-le|--true-two-byte-be]\n", stderr);
  return 64;
}
